from pathlib import Path
from datetime import datetime
import os, sys, shutil, secrets, subprocess, re

ROOT=Path.cwd().resolve()
C=ROOT/"src/autonomous/autonomous_mitigation_controller_v1.py"
R=ROOT/"src/integration/smartsoc_live_receiver_v2.py"
M=ROOT/"src/integration/local_approval_console_v1.py"
T=ROOT/"tests/test_local_approval_console_v1.py"
TOKEN=ROOT/".secrets/smartsoc_approval_console.token"
MODULE_SOURCE='\nfrom __future__ import annotations\nimport os, sqlite3, uuid, getpass\nfrom contextlib import contextmanager\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\n\nACTION = "PROCESS_TERMINATION"\nTTL_SECONDS = 300\n\ndef _now():\n    return datetime.now(timezone.utc)\ndef _iso(value):\n    return value.astimezone(timezone.utc).isoformat()\ndef _parse(value):\n    dt = datetime.fromisoformat(value)\n    if dt.tzinfo is None:\n        raise ValueError("timezone required")\n    return dt.astimezone(timezone.utc)\ndef _root():\n    return Path(__file__).resolve().parents[2]\ndef db_path():\n    return Path(os.environ["SMARTSOC_APPROVAL_DB"]).resolve() if os.getenv("SMARTSOC_APPROVAL_DB") else _root()/"reports/authorization/local_approval.sqlite3"\ndef token_path():\n    return Path(os.environ["SMARTSOC_APPROVAL_TOKEN_FILE"]).resolve() if os.getenv("SMARTSOC_APPROVAL_TOKEN_FILE") else _root()/".secrets/smartsoc_approval_console.token"\ndef _connect():\n    p=db_path(); p.parent.mkdir(parents=True,exist_ok=True)\n    c=sqlite3.connect(str(p),timeout=10,isolation_level=None); c.row_factory=sqlite3.Row\n    c.execute("PRAGMA journal_mode=WAL")\n    c.execute("CREATE TABLE IF NOT EXISTS requests(request_id TEXT PRIMARY KEY, alert_id TEXT NOT NULL, rule_id TEXT NOT NULL, action TEXT NOT NULL, process_name TEXT NOT NULL, pid INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, actor TEXT, decided_at TEXT, consumed_at TEXT)")\n    c.execute("CREATE INDEX IF NOT EXISTS request_binding ON requests(alert_id,rule_id,action,process_name,pid,status)")\n    return c\n@contextmanager\ndef _db():\n    c=_connect()\n    try:\n        yield c\n    finally:\n        c.close()\ndef _val(d,*keys):\n    for key in keys:\n        if d.get(key) is not None and str(d[key]).strip(): return d[key]\n    return None\ndef _binding(d,alert_id=None,rule_id=None):\n    if not isinstance(d,dict): return None\n    alert=alert_id or _val(d,"alert_id","wazuh_alert_id","id")\n    rule=rule_id or _val(d,"rule_id","wazuh_rule_id")\n    mit=d.get("mitigation")\n    m=mit if isinstance(mit,dict) else d\n    action=_val(m,"action","type","mitigation_type","mitigation_action","recommended_action")\n    if not action and isinstance(mit,str): action=mit\n    pid=_val(m,"pid","process_id","target_pid")\n    proc=_val(m,"process_name","process","target_process")\n    target=d.get("target")\n    if isinstance(target,dict):\n        pid=pid or _val(target,"pid","process_id")\n        proc=proc or _val(target,"process_name","process")\n    try: pid=int(pid)\n    except (TypeError,ValueError): return None\n    if not all((alert,rule,action,proc)) or pid<=0 or str(action).upper()!=ACTION: return None\n    return {"alert_id":str(alert),"rule_id":str(rule),"action":ACTION,"process_name":str(proc).strip().lower(),"pid":pid}\ndef register_pending_from_reasoning_result(d,alert_id,rule_id):\n    b=_binding(d,alert_id,rule_id)\n    if not b: return {"registered":False,"reason":"INCOMPLETE_OR_UNSUPPORTED_BINDING"}\n    t=_now()\n    with _db() as c:\n        row=c.execute("SELECT request_id FROM requests WHERE alert_id=? AND rule_id=? AND action=? AND process_name=? AND pid=? AND status=\'PENDING\' AND expires_at>? ORDER BY created_at DESC LIMIT 1",(b["alert_id"],b["rule_id"],b["action"],b["process_name"],b["pid"],_iso(t))).fetchone()\n        if row: return {"registered":True,"request_id":row["request_id"],"status":"PENDING"}\n        rid=str(uuid.uuid4())\n        c.execute("INSERT INTO requests VALUES(?,?,?,?,?,?,\'PENDING\',?,?,NULL,NULL,NULL)",(rid,b["alert_id"],b["rule_id"],b["action"],b["process_name"],b["pid"],_iso(t),_iso(t+timedelta(seconds=TTL_SECONDS))))\n    return {"registered":True,"request_id":rid,"status":"PENDING"}\ndef bind_event_context(d,alert_id,rule_id):\n    if not isinstance(d,dict): return d\n    out=dict(d); out["alert_id"]=str(alert_id or ""); out["rule_id"]=str(rule_id or ""); return out\ndef list_requests():\n    t=_iso(_now())\n    with _db() as c:\n        c.execute("UPDATE requests SET status=\'EXPIRED\' WHERE status IN (\'PENDING\',\'APPROVED\') AND expires_at<=?",(t,))\n        return [dict(r) for r in c.execute("SELECT * FROM requests WHERE status IN (\'PENDING\',\'APPROVED\') ORDER BY created_at DESC LIMIT 200")]\ndef decide_request(request_id,decision,actor):\n    decision=str(decision).upper(); actor=str(actor).strip(); t=_now()\n    if decision not in ("APPROVED","DENIED") or not actor or len(actor)>128: return {"ok":False,"reason":"INVALID_INPUT"}\n    with _db() as c:\n        c.execute("BEGIN IMMEDIATE")\n        row=c.execute("SELECT * FROM requests WHERE request_id=?",(str(request_id),)).fetchone()\n        if not row: c.execute("ROLLBACK"); return {"ok":False,"reason":"NOT_FOUND"}\n        if row["status"]!="PENDING": c.execute("ROLLBACK"); return {"ok":False,"reason":"NOT_PENDING","status":row["status"]}\n        if _parse(row["expires_at"])<=t:\n            c.execute("UPDATE requests SET status=\'EXPIRED\' WHERE request_id=?",(str(request_id),)); c.execute("COMMIT")\n            return {"ok":False,"reason":"EXPIRED"}\n        c.execute("UPDATE requests SET status=?,actor=?,decided_at=? WHERE request_id=? AND status=\'PENDING\'",(decision,actor,_iso(t),str(request_id)))\n        c.execute("COMMIT")\n    return {"ok":True,"status":decision,"request_id":str(request_id),"actor":actor}\ndef consume_approval(d):\n    b=_binding(d)\n    if not b: return {"authorized":False,"reason":"INVALID_BINDING"}\n    t=_now()\n    with _db() as c:\n        c.execute("BEGIN IMMEDIATE")\n        c.execute("UPDATE requests SET status=\'EXPIRED\' WHERE status IN (\'PENDING\',\'APPROVED\') AND expires_at<=?",(_iso(t),))\n        row=c.execute("SELECT * FROM requests WHERE alert_id=? AND rule_id=? AND action=? AND process_name=? AND pid=? AND status=\'APPROVED\' AND expires_at>? ORDER BY decided_at DESC LIMIT 1",(b["alert_id"],b["rule_id"],b["action"],b["process_name"],b["pid"],_iso(t))).fetchone()\n        if not row: c.execute("ROLLBACK"); return {"authorized":False,"reason":"NO_MATCHING_APPROVAL"}\n        n=c.execute("UPDATE requests SET status=\'CONSUMED\',consumed_at=? WHERE request_id=? AND status=\'APPROVED\'",(_iso(t),row["request_id"])).rowcount\n        if n!=1: c.execute("ROLLBACK"); return {"authorized":False,"reason":"ALREADY_CONSUMED"}\n        c.execute("COMMIT")\n    return {"authorized":True,"request_id":row["request_id"],"actor":row["actor"]}\ndef execute_authorized_client_call(client,reasoning_result):\n    auth=consume_approval(reasoning_result)\n    if not auth.get("authorized"):\n        return {"success":False,"verified":False,"status":"AUTHORIZATION_BLOCKED","reason":auth.get("reason"),"victim_client_invoked":False,"endpoint_modified":False}\n    result=client.execute(reasoning_result)\n    result=dict(result) if isinstance(result,dict) else {"success":False,"verified":False,"status":"INVALID_CLIENT_RESULT"}\n    result.update(victim_client_invoked=True,authorization_request_id=auth["request_id"],authorization_actor=auth["actor"])\n    return result\ndef run_console():\n    expected=token_path().read_text(encoding="utf-8").strip() if token_path().exists() else ""\n    supplied=getpass.getpass("SmartSOC local approval token: ")\n    if len(expected)<32 or not __import__("hmac").compare_digest(supplied,expected):\n        raise SystemExit("Authentication failed.")\n    actor=input("Operator label for audit (not a separate identity proof): ").strip()\n    if not actor or len(actor)>128: raise SystemExit("Invalid operator label.")\n    print("Authenticated local approval console. Mitigation remains disabled.")\n    while True:\n        requests=list_requests()\n        print("\\\\nActive requests:")\n        if not requests: print("  (none)")\n        for i,r in enumerate(requests,1):\n            print(f"{i}. {r[\'status\']} alert={r[\'alert_id\']} rule={r[\'rule_id\']} action={r[\'action\']} process={r[\'process_name\']} pid={r[\'pid\']} expires={r[\'expires_at\']} id={r[\'request_id\']}")\n        choice=input("\\\\nEnter request number to decide, R to refresh, Q to quit: ").strip().lower()\n        if choice=="q": break\n        if choice=="r": continue\n        try: item=requests[int(choice)-1]\n        except (ValueError,IndexError): print("Invalid selection."); continue\n        if item["status"]!="PENDING": print("Only PENDING requests can be decided."); continue\n        decision=input("Type APPROVE or DENY: ").strip().upper()\n        if decision not in ("APPROVE","DENY"): print("No decision recorded."); continue\n        if decision=="APPROVE":\n            confirm=input("To confirm this exact alert/rule/process/PID, type APPROVE: ").strip()\n            if confirm!="APPROVE": print("Approval cancelled."); continue\n        result=decide_request(item["request_id"],"APPROVED" if decision=="APPROVE" else "DENIED",actor)\n        print(result)\nif __name__=="__main__": run_console()\n'
TEST_SOURCE='\nimport os, sys, tempfile, unittest\nfrom pathlib import Path\nfrom unittest.mock import Mock\nsys.path.insert(0,str(Path(__file__).resolve().parents[1]/"src"))\nfrom integration import local_approval_console_v1 as a\nclass ApprovalTests(unittest.TestCase):\n    def setUp(self):\n        self.tmp=tempfile.TemporaryDirectory(); self.old=os.getenv("SMARTSOC_APPROVAL_DB")\n        os.environ["SMARTSOC_APPROVAL_DB"]=str(Path(self.tmp.name)/"test.sqlite3")\n        self.event={"alert_id":"A-1","rule_id":"92031","mitigation":{"action":"PROCESS_TERMINATION","process_name":"notepad.exe","pid":4321}}\n        self.client=Mock(); self.client.execute.return_value={"success":True,"verified":True,"status":"MOCKED"}\n    def tearDown(self):\n        if self.old is None: os.environ.pop("SMARTSOC_APPROVAL_DB",None)\n        else: os.environ["SMARTSOC_APPROVAL_DB"]=self.old\n        self.tmp.cleanup()\n    def register(self): return a.register_pending_from_reasoning_result(self.event,"A-1","92031")\n    def test_no_approval_blocks_without_client_call(self):\n        r=a.execute_authorized_client_call(self.client,self.event)\n        self.assertEqual(r["status"],"AUTHORIZATION_BLOCKED"); self.client.execute.assert_not_called()\n    def test_rule_mismatch_blocks(self):\n        self.register(); d=dict(self.event,rule_id="other")\n        self.assertEqual(a.execute_authorized_client_call(self.client,d)["status"],"AUTHORIZATION_BLOCKED")\n        self.client.execute.assert_not_called()\n    def test_approval_is_one_time_and_client_is_mocked(self):\n        q=self.register(); self.assertTrue(q["registered"])\n        self.assertTrue(a.decide_request(q["request_id"],"APPROVED","unit-test-analyst")["ok"])\n        r=a.execute_authorized_client_call(self.client,self.event)\n        self.assertEqual(r["status"],"MOCKED"); self.assertTrue(r["victim_client_invoked"])\n        self.client.execute.assert_called_once_with(self.event)\n        self.assertEqual(a.execute_authorized_client_call(self.client,self.event)["status"],"AUTHORIZATION_BLOCKED")\n        self.assertEqual(self.client.execute.call_count,1)\n    def test_denial_blocks(self):\n        q=self.register(); a.decide_request(q["request_id"],"DENIED","unit-test-analyst")\n        self.assertEqual(a.execute_authorized_client_call(self.client,self.event)["status"],"AUTHORIZATION_BLOCKED")\n        self.client.execute.assert_not_called()\n    def test_unsupported_action_not_queued(self):\n        d={"alert_id":"A","rule_id":"R","mitigation":{"action":"ISOLATE_HOST","process_name":"x.exe","pid":1}}\n        self.assertFalse(a.register_pending_from_reasoning_result(d,"A","R")["registered"])\nif __name__=="__main__": unittest.main()\n'

def abort(message):
    print("ABORTED:",message)
    raise SystemExit(2)
if not (ROOT/"src").is_dir() or not (ROOT/"tests").is_dir() or not C.is_file() or not R.is_file():
    abort("Run from SmartSOC-AI project root; required source files missing.")
ct=C.read_text(encoding="utf-8"); rt=R.read_text(encoding="utf-8")
cfg=(ROOT/"src/integration/execution_config_v1.py").read_text(encoding="utf-8")
# Source calls may span multiple lines; match whitespace without weakening uniqueness checks.
controller_call_re = re.compile(r"self\.victim_client\.execute\(\s*reasoning_result\s*\)")
receiver_call_re = re.compile(r"mitigation_controller\.execute\(\s*reasoning_result\s*\)")
if len(controller_call_re.findall(ct)) != 1:
    abort(f"Expected exactly one controller client call; found {len(controller_call_re.findall(ct))}.")
if rt.count("if not MITIGATION_ENABLED:") != 1:
    abort(f"Expected exactly one receiver mitigation gate; found {rt.count('if not MITIGATION_ENABLED:')}.")
if len(receiver_call_re.findall(rt)) != 1:
    abort(f"Expected exactly one receiver controller call; found {len(receiver_call_re.findall(rt))}.")
if "MITIGATION_ENABLED = False" not in rt: abort("Receiver mitigation is not explicitly disabled.")
for flag in ("EXECUTION_LAYER_ENABLED = False","AUTOMATIC_EXECUTION = False","AUTOMATIC_CONTAINMENT = False"):
    if flag not in cfg: abort(f"Required safe policy flag is not explicitly disabled: {flag}")
future="from __future__ import annotations\n"
if future not in ct or future not in rt: abort("Expected future-import anchor missing.")
cn, controller_subs = controller_call_re.subn(
    "execute_authorized_client_call(self.victim_client, reasoning_result)", ct, count=1
)
if controller_subs != 1: abort("Controller call replacement did not match exactly once.")
cn=cn.replace(future,future+"from integration.local_approval_console_v1 import execute_authorized_client_call\n",1)
rn, receiver_subs = receiver_call_re.subn(
    "mitigation_controller.execute(bind_event_context(reasoning_result, alert_id, rule_id))", rt, count=1
)
if receiver_subs != 1: abort("Receiver call replacement did not match exactly once.")
imp="from production_inference_windows_apt_v4_1 import ("
if rn.count(imp)!=1: abort("Receiver import anchor mismatch.")
rn=rn.replace(imp,"from integration.local_approval_console_v1 import (\n    bind_event_context,\n    register_pending_from_reasoning_result,\n)\n\n"+imp,1)
match=re.search(r"(?m)^([ \\t]*)if not MITIGATION_ENABLED:[ \\t]*$",rn)
if not match: abort("Could not determine receiver gate indentation.")
indent=match.group(1)
rn=rn[:match.start()]+indent+"register_pending_from_reasoning_result(reasoning_result, alert_id, rule_id)\n"+indent+"if not MITIGATION_ENABLED:"+rn[match.end():]
stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
backup=ROOT/"reports/backups"/f"local_approval_milestone_{stamp}"
backup.mkdir(parents=True,exist_ok=False)
for p in (C,R,M,T):
    if p.exists():
        dest=backup/p.relative_to(ROOT); dest.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,dest)
print("Timestamped backup:",backup)
M.parent.mkdir(parents=True,exist_ok=True); T.parent.mkdir(parents=True,exist_ok=True)
M.write_text(MODULE_SOURCE,encoding="utf-8",newline="\n")
T.write_text(TEST_SOURCE,encoding="utf-8",newline="\n")
C.write_text(cn,encoding="utf-8",newline="\n")
R.write_text(rn,encoding="utf-8",newline="\n")
TOKEN.parent.mkdir(parents=True,exist_ok=True)
if not TOKEN.exists(): TOKEN.write_text(secrets.token_urlsafe(48)+"\n",encoding="utf-8")
try: subprocess.run(["icacls",str(TOKEN),"/inheritance:r","/grant:r",f"{os.getenv('USERNAME','*')}:(R)"],capture_output=True,check=False)
except Exception: pass
print("Compile checks and mocked tests; no console start or endpoint calls.")
p=subprocess.run([sys.executable,"-m","py_compile",str(M),str(T),str(C),str(R)],cwd=ROOT)
if p.returncode: abort(f"Compile failed. Keep mitigation disabled; restore C and R from {backup}")
p=subprocess.run([sys.executable,"-m","unittest","discover","-s",str(ROOT/"tests"),"-p","test_local_approval_console_v1.py","-v"],cwd=ROOT)
if p.returncode: abort(f"Mocked tests failed. Keep mitigation disabled; restore C and R from {backup}")
print("SUCCESS: execution flags unchanged; console not started.")
print("To start console later: $env:PYTHONPATH=(Join-Path (Get-Location) 'src'); python -m integration.local_approval_console_v1")
print("Token file:",TOKEN)
print("Backup:",backup)
